CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('customer','employee','owner')),active BOOLEAN NOT NULL DEFAULT TRUE,permissions JSONB NOT NULL DEFAULT '[]',phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL,attributes JSONB NOT NULL DEFAULT '[]',active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS suppliers(id SERIAL PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS locations(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS products(id SERIAL PRIMARY KEY,sku TEXT UNIQUE NOT NULL,name TEXT NOT NULL,category_id INTEGER NOT NULL REFERENCES categories(id),price NUMERIC(14,0) NOT NULL DEFAULT 0 CHECK(price>=0),unit TEXT NOT NULL DEFAULT 'cái',description TEXT NOT NULL DEFAULT '',image TEXT NOT NULL DEFAULT '',datasheet TEXT NOT NULL DEFAULT '',pinout TEXT NOT NULL DEFAULT '',specs JSONB NOT NULL DEFAULT '{}',active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS stock(product_id INTEGER REFERENCES products(id),location_id INTEGER REFERENCES locations(id),quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0),PRIMARY KEY(product_id,location_id));
CREATE TABLE IF NOT EXISTS carts(user_id INTEGER PRIMARY KEY REFERENCES users(id),lines JSONB NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS boms(id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id),name TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',lines JSONB NOT NULL DEFAULT '[]',updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS orders(id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id),request_key TEXT NOT NULL,request_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','shipped','delivering','completed','cancelled','rejected')),recipient TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',lines JSONB NOT NULL,total NUMERIC(16,0) NOT NULL,history JSONB NOT NULL DEFAULT '[]',paid BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW(),completed_at TIMESTAMPTZ,UNIQUE(user_id,request_key));
CREATE TABLE IF NOT EXISTS vouchers(id SERIAL PRIMARY KEY,type TEXT NOT NULL CHECK(type IN ('in','out','sale','adjust','transfer')),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','confirmed')),supplier_id INTEGER REFERENCES suppliers(id),order_id INTEGER REFERENCES orders(id),reference_id INTEGER REFERENCES vouchers(id),reason TEXT NOT NULL DEFAULT '',lines JSONB NOT NULL,created_by INTEGER REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT NOW(),confirmed_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS one_sale_per_order ON vouchers(order_id) WHERE type='sale';
CREATE TABLE IF NOT EXISTS movements(id SERIAL PRIMARY KEY,voucher_id INTEGER REFERENCES vouchers(id),product_id INTEGER REFERENCES products(id),location_id INTEGER REFERENCES locations(id),delta INTEGER NOT NULL,balance INTEGER NOT NULL,actor INTEGER REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit(id SERIAL PRIMARY KEY,actor INTEGER REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,before_data JSONB,after_data JSONB,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),store_name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',low_stock INTEGER NOT NULL DEFAULT 10 CHECK(low_stock>=0));
CREATE INDEX IF NOT EXISTS order_status_idx ON orders(status);
CREATE INDEX IF NOT EXISTS movement_time_idx ON movements(created_at);
CREATE INDEX IF NOT EXISTS product_category_idx ON products(category_id);
